SELECT d.id, d.user_id, d.department_id, dp.name AS department_name, d.doctor_no, d.real_name, d.title, d.specialty, d.introduction, d.avatar_url, d.consultation_fee, d.status, u.username, u.status AS account_status FROM doctor d JOIN department dp ON dp.id = d.department_id JOIN sys_user u ON u.id = d.user_id WHERE d.deleted = 0 AND d.department_id IN
#{id}
AND d.id = #{doctorId}

SELECT COUNT(*)
  FROM doctor
 WHERE deleted = 0

   AND id = #{doctorId}

   AND department_id IN

     #{id}

