SELECT a.*, d.real_name AS doctor_name, dp.name AS department_name FROM appointment a JOIN doctor d ON d.id = a.doctor_id JOIN department dp ON dp.id = a.department_id WHERE a.patient_id = #{patientId} AND a.department_id IN
